import java.util.*;

class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        ListNode cur = head;
        while (cur != null && cur.next != null) {
            if (cur.next.val == cur.val) cur.next = cur.next.next; // drop the copy, stay here
            else cur = cur.next;
        }
        return head;
    }
}

